MOD = 1000000007

def count_permutations(n):
    if n == 0:
        return 1
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1
    dp[1] = 1
    for i in range(2, n + 1):
        dp[i] = (dp[i - 1] + dp[i - 2]) % MOD
    return dp[n]

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    N = int(data[0])
    pairs = [(int(data[2*i+1]), int(data[2*i+2])) for i in range(N)]

    fixed = 0
    cycles = []
    visited = [False] * (2 * N + 1)

    for i in range(1, 2 * N + 1):
        if not visited[i]:
            cycle_length = 0
            x = i
            while not visited[x]:
                visited[x] = True
                x = pairs[x-1][1]
                cycle_length += 1
            if cycle_length > 1:
                cycles.append(cycle_length)
            elif cycle_length == 1:
                fixed += 1

    result = 1
    for cycle in cycles:
        result = (result * count_permutations(cycle)) % MOD

    print((result * pow(2, fixed, MOD)) % MOD)

if __name__ == "__main__":
    main()
